-- AGT-11: one row for every stage output, versioned per run and kind. Rows are only ever added.
-- id is generated by the database and gives the order in which the artifacts were stored.
-- content is the validated JSON as text; fingerprint is the SHA-256 hash of exactly that text, as 64 hexadecimal characters.
-- consumed holds the artifact versions that went into the prompt, one "kind:version:fingerprint" entry each, joined by ";" (empty for none).
-- created_at is filled by the database; the application does not set or read it.
-- The unique key stops two writers from storing the same version of a kind for a run.
CREATE TABLE artifact (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES runs (id),
    kind VARCHAR(255) NOT NULL,
    version INTEGER NOT NULL,
    content TEXT NOT NULL,
    summary TEXT NOT NULL,
    fingerprint VARCHAR(64) NOT NULL,
    role VARCHAR(255) NOT NULL,
    role_version VARCHAR(255) NOT NULL,
    profile VARCHAR(255) NOT NULL,
    model VARCHAR(255) NOT NULL,
    consumed TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_artifact_run_kind_version UNIQUE (run_id, kind, version)
);
